//! Importing files written by another program (IfcOpenShell), generated by
//! `scripts/make_ifc_fixtures.py`: the same invented house in IFC4 (metres,
//! walls with an axis) and in IFC2X3 (millimetres, walls without one).

use archisim_core::{
    DoorOperation, Hand, Model, OpeningKind, Point2, ReferenceLine, SlabFunction, WallFunction,
    WallSide, WindowOperation,
};
use archisim_ifc::{differences, export_ifc, import_ifc, ExportOptions, Imported};

fn import(name: &str) -> Imported {
    let path = format!("{}/tests/fixtures/{name}", env!("CARGO_MANIFEST_DIR"));
    let text = std::fs::read_to_string(&path).unwrap();
    import_ifc(&text).unwrap()
}

fn near(a: f64, b: f64) -> bool {
    (a - b).abs() < 1e-6
}

fn check(name: &str) {
    let Imported { model, report } = import(name);
    let r = report.to_string();
    assert_eq!(model.project_name, "Casa de prueba");
    let levels = model.levels();
    assert_eq!(levels.len(), 2, "{r}");
    assert!(near(levels[1].elevation, 3.0));

    // Five walls; the façade turned so its exterior is outside, on the
    // left of each wall, the render first, the line on the outer face.
    assert_eq!(report.walls, 5, "{r}");
    let walls: Vec<_> = model.walls().collect();
    let south = walls
        .iter()
        .find(|w| w.start.y.abs() < 1e-6 && w.end.y.abs() < 1e-6)
        .unwrap();
    assert!(
        south.start.distance(Point2::new(10.0, 0.0)) < 1e-6,
        "{south:?}"
    );
    assert!(south.end.distance(Point2::new(0.0, 0.0)) < 1e-6);
    assert_eq!(south.reference, ReferenceLine::ExteriorFace);
    assert!(near(south.height, 2.8));
    let facade = model.wall_type(south.wall_type).unwrap();
    assert_eq!(facade.name, "Fachada 4 capas");
    assert_eq!(facade.function, WallFunction::Exterior);
    let first = model.material(facade.layers[0].material).unwrap();
    assert_eq!(first.name, "Mortero monocapa");
    assert!(near(facade.thickness(), 0.195));
    // Every façade wall goes clockwise round the house.
    let mut turn = 0.0;
    for w in walls.iter().filter(|w| w.wall_type == south.wall_type) {
        turn += w.start.x * w.end.y - w.end.x * w.start.y;
    }
    assert!(turn < 0.0, "the façade must run clockwise");
    let partition = walls
        .iter()
        .find(|w| w.wall_type != south.wall_type)
        .unwrap();
    let pt = model.wall_type(partition.wall_type).unwrap();
    assert_eq!(pt.function, WallFunction::Interior);
    assert!(near(pt.thickness(), 0.1));

    // The entrance door: 7 m from the new start of the south wall.
    assert_eq!((report.doors, report.windows), (2, 1), "{r}");
    let door = model.openings_in_wall(south.id).next().unwrap();
    assert!(near(door.along, 7.0), "{door:?}");
    assert!(near(door.sill, 0.0));
    assert_eq!(door.opens_to, WallSide::Interior);
    assert_eq!(door.hand, Hand::Left);
    let dt = model.opening_type(door.opening_type).unwrap();
    assert_eq!(dt.kind, OpeningKind::Door(DoorOperation::SingleSwing));
    assert!(near(dt.width, 1.0) && near(dt.height, 2.1), "{dt:?}");
    assert!(
        near(dt.frame_depth, 0.07) && near(dt.frame_width, 0.06),
        "{dt:?}"
    );
    assert_eq!(model.material(dt.frame_material).unwrap().name, "Madera");

    // The window, two side-hung leaves.
    let window = model
        .openings()
        .find(|o| model.opening_type(o.opening_type).unwrap().is_window())
        .unwrap();
    let wt = model.opening_type(window.opening_type).unwrap();
    assert_eq!(
        wt.kind,
        OpeningKind::Window(WindowOperation::DoubleCasement)
    );
    assert!(near(wt.width, 1.5) && near(wt.height, 1.2));
    assert!(
        near(window.sill, 1.0) && near(window.along, 3.5),
        "{window:?}"
    );
    assert_eq!(model.material(wt.panel_material).unwrap().category, "glass");

    // The partition door, without lining sizes: usual frame.
    let inner = model.openings_in_wall(partition.id).next().unwrap();
    assert_eq!(inner.hand, Hand::Right);
    assert!(near(inner.along, 2.0));

    // The ground slab, top face at ±0.
    assert_eq!(report.slabs, 1, "{r}");
    let slab = model.slabs().next().unwrap();
    assert!(near(slab.top_offset, 0.0));
    assert!(near(slab.area(), 70.0));
    let st = model.slab_type(slab.slab_type).unwrap();
    assert_eq!(st.function, SlabFunction::BaseSlab);
    assert!(near(st.thickness(), 0.2));

    // Left out: the column and the empty opening.
    assert_eq!(report.skipped_count(), 2, "{r}");
    assert!(
        r.contains("pilares") && r.contains("hueco sin puerta"),
        "{r}"
    );

    // What was imported survives our own export.
    assert_round_trip(&model);
}

fn assert_round_trip(model: &Model) {
    let ifc = export_ifc(model, &ExportOptions::default());
    let back = import_ifc(&ifc).unwrap();
    let diffs = differences(model, &back.model);
    assert!(diffs.is_empty(), "{}", diffs.join("\n"));
}

#[test]
fn ifcopenshell_ifc4_in_metres() {
    check("ifcopenshell_ifc4_m.ifc");
}

#[test]
fn ifcopenshell_ifc2x3_in_millimetres() {
    let imported = import("ifcopenshell_ifc2x3_mm.ifc");
    assert_eq!(imported.report.schema, "IFC2X3");
    assert!(imported.report.to_string().contains("milímetros"));
    check("ifcopenshell_ifc2x3_mm.ifc");
}

#[test]
fn both_versions_give_the_same_building() {
    let a = import("ifcopenshell_ifc4_m.ifc").model;
    let b = import("ifcopenshell_ifc2x3_mm.ifc").model;
    // Same geometry and types; GlobalIds differ between the two files, so
    // compare walls by position.
    for w in a.walls() {
        assert!(
            b.walls().any(|v| v.start.distance(w.start) < 1e-6
                && v.end.distance(w.end) < 1e-6
                && v.reference == w.reference),
            "{w:?}"
        );
    }
}
